function catStage(){const lv=level();return lv>=8?['수호자','별빛 왕관',4]:lv>=5?['단짝','별 목걸이',3]:lv>=3?['친구','리본',2]:['첫 만남','작은 새싹',1]}
function catCompanion(size='small'){
 const mood=moodInfo(dstate().mood),stage=catStage();
 return `<div class="companion companion-${size}"><div class="companion-portrait"><img src="jogaki-cat.webp" alt="핑크 체크 쿠션에 누운 귀여운 크림색 고양이 ${esc(petLabel())}" loading="eager"/></div><div class="companion-copy"><span class="companion-eyebrow">MY COMPANION · LV.${level()}</span><strong>${esc(petLabel())} <span class="companion-stage">${stage[0]}</span></strong><div class="companion-speech">${esc(mood?mood[3]:'오늘도 와줘서 고마워!')}</div></div></div>`;
}

const itemCatalog=[['leaf','숲의 책갈피','오늘의 작은 발견을 기억하는 잎사귀'],['key','오래된 열쇠','아직 열리지 않은 서랍의 열쇠'],['star','별빛 조각','평범한 저녁에 발견한 반짝임'],['cup','온기의 잔','잘 쉬었던 순간의 기념품'],['bookmark','은빛 책갈피','어떤 페이지에 머문 시간'],['moon','달의 파편','고요한 밤을 담은 조각'],['book','낡은 수첩','쌓여 가는 기록의 흔적'],['mail','봉인된 편지','읽고 싶은 마음을 간직한 편지'],['spark','유리 구슬','눈에 띄지 않는 빛을 담은 보물'],['heart','작은 하트','나를 아껴 준 하루의 표시'],['archive','나무 상자','소중한 순간을 담는 수집함'],['sun','오전의 빛','시작하는 마음을 닮은 빛']];
const weatherCities={서울:[37.5665,126.978],천안:[36.8151,127.1139],아산:[36.7898,127.0018],대전:[36.3504,127.3845],서산:[36.7845,126.4503],홍성:[36.601,126.6608],당진:[36.8899,126.6459],서천:[36.0809,126.691],공주:[36.4465,127.119],보령:[36.333,126.612],논산:[36.187,127.099],부여:[36.2756,126.91],부산:[35.1796,129.0756],인천:[37.4563,126.7052]};
const defaultRoutines=[{id:'r1',text:'물 한 잔으로 시작하기',time:'08:00',days:[0,1,2,3,4,5,6]},{id:'r2',text:'10분 산책 또는 스트레칭',time:'18:30',days:[0,1,2,3,4,5,6]},{id:'r3',text:'오늘의 영단어·일본어 확인',time:'20:00',days:[0,1,2,3,4,5,6]},{id:'r4',text:'오늘의 한 줄 남기기',time:'21:30',days:[0,1,2,3,4,5,6]}];
const blankDay=()=>({done:{},note:'',goal:'',goalDone:false,gratitudes:['','',''],mood:'',meals:[],studied:{},letterRead:false,rewardId:null,updatedAt:0});
function defaultState(){return{version:2,routines:defaultRoutines,days:{},settings:{city:'서울',nickname:'나',petName:'조각이',firebaseConfig:null},routinesUpdatedAt:0,settingsUpdatedAt:0}}
let state=defaultState();try{const stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored?.version===2&&stored.days&&Array.isArray(stored.routines))state={...defaultState(),...stored,settings:{...defaultState().settings,...stored.settings}}}catch(err){console.warn('local data unreadable',err)}
let pickedFoodId=null;let foodCategory='전체';let foodSearch='';let foodShowAll=false;let mealQty=1;let activeDate=todayISO();let page='today';let calendarMonth=activeDate.slice(0,7);let toastTimer;let showLetter=false;let newDays=[0,1,2,3,4,5,6];let editingRoutineId=null;let lastTheme='';let weather={state:'idle'};let cloudReady=false;let cloudStatus='연동 안 됨';let roomTab='items';
const dstate=(date=activeDate)=>state.days[date]||blankDay();
const activeRoutines=(date=activeDate)=>state.routines.filter(r=>r.days.includes(dayOfWeek(date)));
const doneCount=(date=activeDate)=>activeRoutines(date).filter(r=>dstate(date).done[r.id]).length;
const completePercent=(date=activeDate)=>{const n=activeRoutines(date).length;return n?Math.round(doneCount(date)/n*100):0};
function dailyXP(d){const s=state.days[d];if(!s)return 0;return state.routines.filter(r=>r.days.includes(dayOfWeek(d))&&s.done[r.id]).length*15+(s.note?.trim()?12:0)+(s.goal?.trim()?4:0)+Math.min((s.gratitudes||[]).filter(Boolean).length,3)*3+Math.min(s.meals?.length||0,4)*5+Object.values(s.studied||{}).filter(Boolean).length*8+(s.letterRead?5:0)}
const earnedXP=()=>Object.keys(state.days).reduce((t,d)=>t+dailyXP(d),0);
const level=()=>Math.floor(earnedXP()/180)+1;
const lvlProgress=()=>earnedXP()%180;
const rewardCandidates=()=>itemCatalog.filter((v,i)=>!Object.values(state.days).some(d=>d.rewardId===i));
const inventory=()=>Object.values(state.days).filter(d=>Number.isInteger(d.rewardId)).map(d=>d.rewardId);
const rewardForDay=date=>hash(date)%itemCatalog.length;
const dailyContent=date=>{const idx=Math.floor((Date.parse(date+'T12:00:00Z')-Date.UTC(2026,0,1))/86400000);return {en:english[((idx%english.length)+english.length)%english.length],ja:japanese[(((idx+5)%japanese.length)+japanese.length)%japanese.length],letter:letters[(((idx+11)%letters.length)+letters.length)%letters.length],quote:quotes[(((idx+3)%quotes.length)+quotes.length)%quotes.length]}};
function persist(sync=true){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){toast('저장 공간이 부족해. 기록을 백업해 줘.')}if(sync&&cloudReady&&window.CloudSync?.save)window.CloudSync.save(state)}
function editDay(date,cb){if(!state.days[date])state.days[date]=blankDay();cb(state.days[date]);state.days[date].updatedAt=Date.now();persist()}
function theme(){const v='light';if(v!==lastTheme){document.documentElement.dataset.theme=v;document.querySelector('meta[name="theme-color"]').content='#f7f7f3';lastTheme=v;document.getElementById('themeBadge').textContent='MINIMAL'}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3100)}
function nav(){const link=(n,icon,label,cls)=>`<button class="${cls}${page===n?' active':''}" data-action="page" data-page="${n}" aria-label="${label}">${ico(icon)}<span>${label}</span></button>`;document.getElementById('sideNav').innerHTML=navItems.map(x=>link(...x,'navitem')).join('');document.getElementById('bottomNav').innerHTML=navItems.map(x=>link(...x,'')).join('')}
function heading(over,title,desc='',buttons=''){return `<div class="page-heading"><div><p class="eyebrow">${over}</p><h1>${title}</h1>${desc?`<p class="intro">${desc}</p>`:''}</div>${buttons?`<div class="heading-action">${buttons}</div>`:''}</div>`}
function dateSwitch(){return `<div class="date-switch"><button class="icon-button" data-action="shift-day" data-shift="-1" aria-label="전날">${ico('chevronLeft')}</button><span>${esc(dateName(activeDate))}</span><button class="icon-button" data-action="shift-day" data-shift="1" aria-label="다음날">${ico('chevronRight')}</button></div>`}
function panelTop(title,right=''){return `<div class="panel-top"><h2>${title}</h2>${right}</div>`}
function levelHTML(){return `<div class="level-panel level-soft"><div class="mini-avatar"><img src="jogaki-cat.webp" alt="${esc(petLabel())}"/></div><div class="lv-data"><strong>${esc(petLabel())} · Lv.${level()} <span class="level-stage">${catStage()[0]}</span></strong><p>${earnedXP()} XP 누적 · 다음 레벨까지 ${180-lvlProgress()} XP</p><div class="progress-track"><div class="progress-bar" style="width:${lvlProgress()/180*100}%"></div></div></div></div>`;}

function favoriteIds(){return Array.isArray(state.settings.foodFavorites)?state.settings.foodFavorites:[]}
function recentIds(){const keys=Object.keys(state.days).sort().reverse();const found=[];for(const d of keys){for(const meal of [...(state.days[d]?.meals||[])].reverse()){if(foods.some(f=>f.id===meal.foodId)&&!found.includes(meal.foodId))found.push(meal.foodId);if(found.length>=15)return found}}return found}
function foodGridHTML(){const fav=favoriteIds(),rec=recentIds();let items=foods.filter(f=>(foodCategory==='전체'||foodCategory==='즐겨찾기'&&fav.includes(f.id)||foodCategory==='최근'&&rec.includes(f.id)||foodCategory===f.category)&&f.name.toLocaleLowerCase().includes(foodSearch.toLocaleLowerCase()));if(foodCategory==='전체')items.sort((a,b)=>Number(fav.includes(b.id))-Number(fav.includes(a.id))||Number(rec.includes(b.id))-Number(rec.includes(a.id))||foods.indexOf(a)-foods.indexOf(b));if(foodCategory==='최근')items.sort((a,b)=>rec.indexOf(a.id)-rec.indexOf(b.id));if(foodCategory==='전체'&&!foodSearch&&!foodShowAll){const prioritized=['sushi','rice','sundubu','stew','pizza','coffee','ramen','friedchicken','eggroll','tteok','latte','kimbap'];const top=[...fav,...rec,...prioritized,...items.map(f=>f.id)];const seen=new Set();items=top.filter(id=>!seen.has(id)&&seen.add(id)).slice(0,12).map(id=>foods.find(f=>f.id===id)).filter(Boolean)}return items.length?items.map(f=>`<div class="food-tile${pickedFoodId===f.id?' is-picked':''}"><button type="button" class="food-choice" data-action="pick-food" data-food="${f.id}" aria-label="${esc(f.name)} ${esc(f.unit)}, ${f.calories} 킬로칼로리 선택"><span class="food-thumb">${foodIcon(f.id)}</span><span class="food-label">${esc(f.name)}</span><small>${f.calories} kcal</small></button><button class="food-favorite${fav.includes(f.id)?' saved':''}" type="button" data-action="food-favorite" data-food="${f.id}" aria-label="${esc(f.name)} 즐겨찾기 ${fav.includes(f.id)?'해제':'추가'}" aria-pressed="${fav.includes(f.id)}">${fav.includes(f.id)?'♥':'♡'}</button></div>`).join(''):`<div class="food-empty">검색 결과가 없어. 다른 음식 이름으로 찾아봐.</div>`}
function foodShowMoreHTML(){if(foodCategory!=='전체'||foodSearch)return '';return `<button class="food-more" type="button" data-action="food-more">${foodShowAll?'자주 먹는 음식만 보기 ↑':'음식 도감 73종 모두 보기 ↓'}</button>`}
function selectedFoodHTML(){const f=foods.find(x=>x.id===pickedFoodId);if(!f)return '';return `<div class="food-portion-info"><div><div class="food-portion-title">${esc(f.name)} <span>${esc(f.unit)}</span></div><p>기본 ${f.calories} kcal · 실제 양과 조리법에 따라 달라져</p></div><div class="food-portion-stepper"><button type="button" data-action="food-quantity" data-direction="-1" ${mealQty<=.5?'disabled':''} aria-label="양 줄이기">−</button><strong>× ${mealQty}</strong><button type="button" data-action="food-quantity" data-direction="1" ${mealQty>=5?'disabled':''} aria-label="양 늘리기">+</button></div></div>`}
function refreshFoodPicker(){const grid=document.getElementById('foodGrid');if(grid)grid.innerHTML=foodGridHTML();const more=document.getElementById('foodShowMore');if(more)more.innerHTML=foodShowMoreHTML();const info=document.getElementById('selectedFoodInfo');if(info){info.hidden=!pickedFoodId;info.innerHTML=selectedFoodHTML()}}

