 return `<section class="story-card home-goal-compact"><div class="story-title"><strong>오늘의 목표</strong><span class="story-trailing">${ico('chevronRight',15)}</span></div><div class="story-body-row"><button type="button" class="round-tick${data.goalDone?' is-done':''}" data-action="goal-done" aria-label="목표 ${data.goalDone?'완료 취소':'완료 표시'}" ${goal?'':'disabled'}>${data.goalDone?ico('check',16):''}</button><button type="button" class="story-content${data.goalDone?' striked':''}" data-action="page" data-page="journal">${esc(goal||'오늘의 목표를 적어볼까?')}</button></div></section>`;
